import{_ as r,a0 as p,w as d,s as o,I as s,x as t,a1 as e,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用命令列工具 Graudit 來查找你代碼中的安全漏洞 | LCTT x X-CMD","titleTemplate":false,"description":"使用命令列工具 Graudit 來查找你代碼中的安全漏洞 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用命令列工具 Graudit 來查找你代碼中的安全漏洞 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用命令列工具 Graudit 來查找你代碼中的安全漏洞 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200827 Use this command-line tool to find security flaws in your code","title":"使用命令列工具 Graudit 來查找你代碼中的安全漏洞","tag":"202009","desc":""},"relativePath":"202009/20200827 Use this command-line tool to find security flaws in your code.md","filePath":"[post].md"}'),u={name:"202009/20200827 Use this command-line tool to find security flaws in your code.md"};function g(h,i,f,b,m,k){const a=p("Link");return d(),o("div",null,[i[29]||(i[29]=s("h1",{id:"使用命令列工具-graudit-來查找你代碼中的安全漏洞",tabindex:"-1"},[t("使用命令列工具 Graudit 來查找你代碼中的安全漏洞 "),s("a",{class:"header-anchor",href:"#使用命令列工具-graudit-來查找你代碼中的安全漏洞","aria-label":"Permalink to “使用命令列工具 Graudit 來查找你代碼中的安全漏洞”"},"​")],-1)),i[30]||(i[30]=s("blockquote",null,[s("p",null,"憑藉廣泛的語言支持，Graudit 可以讓你在開發過程中的審計你的代碼安全。")],-1)),i[31]||(i[31]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/03/114037qhi2h282wghbp74n.jpg",alt:""})],-1)),i[32]||(i[32]=s("p",null,"測試是軟件開發生命週期（SDLC）的重要組成部分，它有幾個階段。今天，我想談談如何在代碼中發現安全問題。",-1)),s("p",null,[i[1]||(i[1]=t("在開發軟件的時候，你不能忽視安全問題。這就是為什麼有一個術語叫 DevSecOps，它的基本職責是識別和解決應用中的安全漏洞。有一些用於檢查 ",-1)),e(a,{href:"https://owasp.org/www-community/vulnerabilities/"},{default:l(()=>[...i[0]||(i[0]=[t("OWASP 漏洞",-1)])]),_:1}),i[2]||(i[2]=t("的開源解決方案，它將通過創建源代碼的威脅模型來得出結果。",-1))]),i[33]||(i[33]=n('<p>處理安全問題有不同的方法，如靜態應用安全測試（SAST）、動態應用安全測試（DAST）、交互式應用安全測試（IAST）、軟件組成分析等。</p><p>靜態應用安全測試在代碼層面運行，通過發現編寫好的代碼中的錯誤來分析應用。這種方法不需要運行代碼，所以叫靜態分析。</p><p>我將重點介紹靜態代碼分析，並使用一個開源工具進行實際體驗。</p><h3 id="為什麼要使用開源工具檢查代碼安全" tabindex="-1">為什麼要使用開源工具檢查代碼安全？ <a class="header-anchor" href="#為什麼要使用開源工具檢查代碼安全" aria-label="Permalink to “為什麼要使用開源工具檢查代碼安全？”">​</a></h3><p>選擇開源軟件、工具和項目作為開發的一部分有很多理由。它不會花費任何金錢，因為你使用的是一個由志趣相投的開發者社區開發的工具，而他們希望幫助其他開發者。如果你有一個小團隊或一個初創公司，找到開源軟件來檢查你的代碼安全是很好的。這樣可以讓你不必單獨僱傭一個 DevSecOps 團隊，讓你的成本降低。</p><p>好的開源工具總是考慮到靈活性，它們應該能夠在任何環境中使用，覆蓋儘可能多的情況。這讓開發人員更容易將該軟件與他們現有的系統連接起來。</p><p>但是有的時候，你可能需要一個功能，而這個功能在你選擇的工具中是不可用的。那麼你就可以選擇復刻其代碼，在其上開發自己的功能，並在你的系統中使用。</p><p>因為，大多數時候，開源軟件是由社區驅動的，開發的速度往往是該工具的用户的加分項，因為他們會根據用户的反饋、問題或 bug 報告來迭代項目。</p><h3 id="使用-graudit-來確保你的代碼安全" tabindex="-1">使用 Graudit 來確保你的代碼安全 <a class="header-anchor" href="#使用-graudit-來確保你的代碼安全" aria-label="Permalink to “使用 Graudit 來確保你的代碼安全”">​</a></h3><p>有各種開源的靜態代碼分析工具可供選擇，但正如你所知道的，工具分析的是代碼本身，這就是為什麼沒有通用的工具適用於所有的編程語言。但其中一些遵循 OWASP 指南，儘量覆蓋更多的語言。</p>',10)),s("p",null,[i[4]||(i[4]=t("在這裏，我們將使用 ",-1)),e(a,{href:"https://github.com/wireghoul/graudit"},{default:l(()=>[...i[3]||(i[3]=[t("Graudit",-1)])]),_:1}),i[5]||(i[5]=t("，它是一個簡單的命令列工具，可以讓我們找到代碼庫中的安全缺陷。它支持不同的語言，但有一個固定的簽名集。",-1))]),s("p",null,[i[7]||(i[7]=t("Graudit 使用的 ",-1)),i[8]||(i[8]=s("code",null,"grep",-1)),i[9]||(i[9]=t(" 是 GNU 許可證下的工具，類似的靜態代碼分析工具還有 Rough Auditing Tool for Security（RATS）、Securitycompass Web Application Analysis Tool（SWAAT）、flawfinder 等。但 Graudit 的技術要求是最低的，並且非常靈活。不過，你可能還是有 Graudit 無法滿足的要求。如果是這樣，你可以看看這個",-1)),e(a,{href:"https://project-awesome.org/mre/awesome-static-analysis"},{default:l(()=>[...i[6]||(i[6]=[t("列表",-1)])]),_:1}),i[10]||(i[10]=t("的其他的選擇。",-1))]),i[34]||(i[34]=n(`<p>我們可以將這個工具安裝在特定的項目下，或者全局命名空間中，或者在特定的用户下，或者任何我們喜歡地方，它很靈活。我們先來克隆一下倉庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/wireghoul/graudit</span></span></code></pre></div><p>現在，我們需要創建一個 Graudit 的符號鏈接，以便我們可以將其作為一個命令使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/bin &amp;&amp; mkdir graudit</span></span>
<span class="line"><span>$ ln --symbolic ~/graudit/graudit ~/bin/graudit</span></span></code></pre></div><p>在 <code>.bashrc</code> （或者你使用的任何 shell 的配置文件）中添加一個別名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#------ .bashrc ------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alias graudit=&quot;~/bin/graudit&quot;</span></span></code></pre></div><p>重新加載 shell：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc # 或</span></span>
<span class="line"><span>$ exex $SHELL</span></span></code></pre></div><p>讓我們通過運行這個來檢查是否成功安裝了這個工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ graudit -h</span></span></code></pre></div><p>如果你得到類似於這樣的結果，那麼就可以了。</p><p><img src="https://opensource.com/sites/default/files/uploads/graudit_1.png" alt="Graudit terminal screen showing help page" title="Graudit terminal screen showing help page"></p><p><em>圖 1 Graudit 幫助頁面</em></p><p>我正在使用我現有的一個項目來測試這個工具。要運行該工具，我們需要傳遞相應語言的資料庫。你會在 signatures 文件夾下找到這些資料庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ graudit -d ~/gradit/signatures/js.db</span></span></code></pre></div><p>我在現有項目中的兩個 JavaScript 文件上運行了它，你可以看到它在控制台中拋出了易受攻擊的代碼。</p><p><img src="https://opensource.com/sites/default/files/uploads/graudit_2.png" alt="JavaScript file showing Graudit display of vulnerable code" title="JavaScript file showing Graudit display of vulnerable code"></p><p><img src="https://opensource.com/sites/default/files/uploads/graudit_3.png" alt="JavaScript file showing Graudit display of vulnerable code" title="JavaScript file showing Graudit display of vulnerable code"></p>`,18)),s("p",null,[i[12]||(i[12]=t("你可以嘗試在你的一個項目上運行這個，項目本身有一個長長的",-1)),e(a,{href:"https://github.com/wireghoul/graudit#databases"},{default:l(()=>[...i[11]||(i[11]=[t("資料庫",-1)])]),_:1}),i[13]||(i[13]=t("列表，用於支持不同的語言。",-1))]),i[35]||(i[35]=s("h3",{id:"graudit-的優點和缺點",tabindex:"-1"},[t("Graudit 的優點和缺點 "),s("a",{class:"header-anchor",href:"#graudit-的優點和缺點","aria-label":"Permalink to “Graudit 的優點和缺點”"},"​")],-1)),i[36]||(i[36]=s("p",null,"Graudit 支持很多語言，這使其成為許多不同系統上的用户的理想選擇。由於它的使用簡單和語言支持廣泛，它可以與其他免費或付費工具相媲美。最重要的是，它們正在開發中，社區也支持其他用户。",-1)),i[37]||(i[37]=s("p",null,"雖然這是一個方便的工具，但你可能會發現很難將某個特定的代碼識別為“易受攻擊”。也許開發者會在未來版本的工具中加入這個功能。但是，通過使用這樣的工具來關注代碼中的安全問題總是好的。",-1)),i[38]||(i[38]=s("h3",{id:"總結",tabindex:"-1"},[t("總結 "),s("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),i[39]||(i[39]=s("p",null,"在本文中，我只介紹了眾多安全測試類型中的一種：靜態應用安全測試。從靜態代碼分析開始很容易，但這只是一個開始。你可以在你的應用開發流水線中添加其他類型的應用安全測試，以豐富你的整體安全意識。",-1)),i[40]||(i[40]=s("hr",null,null,-1)),s("p",null,[i[15]||(i[15]=t("via: ",-1)),e(a,{href:"https://opensource.com/article/20/8/static-code-security-analysis"},{default:l(()=>[...i[14]||(i[14]=[t("https://opensource.com/article/20/8/static-code-security-analysis",-1)])]),_:1})]),s("p",null,[i[20]||(i[20]=t("作者：",-1)),e(a,{href:"https://opensource.com/users/arinoman"},{default:l(()=>[...i[16]||(i[16]=[t("Ari Noman",-1)])]),_:1}),i[21]||(i[21]=t(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...i[17]||(i[17]=[t("lujun9972",-1)])]),_:1}),i[22]||(i[22]=t(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:l(()=>[...i[18]||(i[18]=[t("geekpi",-1)])]),_:1}),i[23]||(i[23]=t(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[19]||(i[19]=[t("wxy",-1)])]),_:1})]),s("p",null,[i[26]||(i[26]=t("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[24]||(i[24]=[t("LCTT",-1)])]),_:1}),i[27]||(i[27]=t(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...i[25]||(i[25]=[t("Linux中國",-1)])]),_:1}),i[28]||(i[28]=t(" 榮譽推出",-1))])])}const v=r(u,[["render",g]]);export{C as __pageData,v as default};
